CREATE TABLE IF NOT EXISTS public.v22_supplier_confirmations (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, purchase_order_id uuid not null references public.purchase_orders(id) on delete cascade, confirmed_at timestamptz not null default now(), supplier_reference text, expected_at timestamptz, confirmed_by uuid references auth.users(id), notes text, created_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS idx_v22_confirmations_po ON public.v22_supplier_confirmations(business_id,purchase_order_id,created_at desc);
CREATE TABLE IF NOT EXISTS public.v22_supplier_confirmation_lines (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, confirmation_id uuid not null references public.v22_supplier_confirmations(id) on delete cascade, purchase_order_line_id uuid not null references public.purchase_order_lines(id) on delete restrict, ingredient_id uuid not null references public.ingredients(id) on delete restrict, confirmed_quantity numeric(24,8) not null check(confirmed_quantity >= 0), unit text not null, created_at timestamptz not null default now(), unique(confirmation_id,purchase_order_line_id));
CREATE INDEX IF NOT EXISTS idx_v22_confirmation_lines_po_line ON public.v22_supplier_confirmation_lines(business_id,purchase_order_line_id);
CREATE TABLE IF NOT EXISTS public.v22_logistics_shipments (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, shipment_type text not null check(shipment_type in ('supplier_po','internal_transfer')), purchase_order_id uuid references public.purchase_orders(id) on delete cascade, stock_transfer_id uuid references public.stock_transfers(id) on delete cascade, supplier_id uuid references public.suppliers(id) on delete restrict, status text not null default 'planned' check(status in ('planned','confirmed','in_transit','out_for_delivery','delivered','cancelled','exception')), carrier_reference text, supplier_reference text, origin_location_id uuid references public.locations(id), destination_location_id uuid references public.locations(id), planned_at timestamptz, confirmed_at timestamptz, dispatched_at timestamptz, expected_at timestamptz, delivered_at timestamptz, created_at timestamptz not null default now(), unique(purchase_order_id), unique(stock_transfer_id), check((shipment_type='supplier_po' and purchase_order_id is not null and stock_transfer_id is null) or (shipment_type='internal_transfer' and stock_transfer_id is not null and purchase_order_id is null)));
CREATE INDEX IF NOT EXISTS idx_v22_shipments_active ON public.v22_logistics_shipments(business_id,status,expected_at);
CREATE INDEX IF NOT EXISTS idx_v22_shipments_supplier ON public.v22_logistics_shipments(business_id,supplier_id,created_at desc);
CREATE TABLE IF NOT EXISTS public.v22_logistics_milestones (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, shipment_id uuid not null references public.v22_logistics_shipments(id) on delete cascade, milestone_code text not null check(milestone_code in ('planned','supplier_confirmed','dispatched','in_transit','out_for_delivery','delivered','exception')), occurred_at timestamptz not null default now(), source text not null default 'user' check(source in ('system','user','supplier')), notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS idx_v22_milestones_shipment ON public.v22_logistics_milestones(business_id,shipment_id,occurred_at desc);
CREATE TABLE IF NOT EXISTS public.v22_supply_exceptions (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, shipment_id uuid references public.v22_logistics_shipments(id) on delete cascade, purchase_order_id uuid references public.purchase_orders(id) on delete cascade, stock_transfer_id uuid references public.stock_transfers(id) on delete cascade, exception_type text not null check(exception_type in ('supplier_confirmation_overdue','eta_breach','partial_confirmation','delivery_overdue','route_blocked')), severity text not null default 'medium' check(severity in ('low','medium','high','critical')), status text not null default 'open' check(status in ('open','acknowledged','resolved')), detected_at timestamptz not null default now(), acknowledged_at timestamptz, resolved_at timestamptz, resolved_by uuid references auth.users(id), details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_v22_open_exception ON public.v22_supply_exceptions(business_id,exception_type,coalesce(shipment_id,'00000000-0000-0000-0000-000000000000'::uuid),coalesce(purchase_order_id,'00000000-0000-0000-0000-000000000000'::uuid),coalesce(stock_transfer_id,'00000000-0000-0000-0000-000000000000'::uuid)) WHERE status in ('open','acknowledged');
CREATE INDEX IF NOT EXISTS idx_v22_exceptions_active ON public.v22_supply_exceptions(business_id,status,severity,detected_at desc);
CREATE TABLE IF NOT EXISTS public.v22_supplier_logistics_metrics (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, supplier_id uuid not null references public.suppliers(id) on delete cascade, shipment_count integer not null default 0, confirmed_count integer not null default 0, on_time_eta_count integer not null default 0, delivered_count integer not null default 0, confirmation_rate numeric(8,4) not null default 0, eta_accuracy_score numeric(8,4) not null default 0, logistics_execution_score numeric(8,4) not null default 0, calculated_at timestamptz not null default now(), unique(business_id,supplier_id));
CREATE INDEX IF NOT EXISTS idx_v22_supplier_logistics_metrics ON public.v22_supplier_logistics_metrics(business_id,supplier_id);
ALTER TABLE public.v22_supplier_confirmations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v22_supplier_confirmation_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v22_logistics_shipments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v22_logistics_milestones ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v22_supply_exceptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v22_supplier_logistics_metrics ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS v22_confirmation_select ON public.v22_supplier_confirmations; CREATE POLICY v22_confirmation_select ON public.v22_supplier_confirmations FOR SELECT USING(is_member(business_id));
DROP POLICY IF EXISTS v22_confirmation_line_select ON public.v22_supplier_confirmation_lines; CREATE POLICY v22_confirmation_line_select ON public.v22_supplier_confirmation_lines FOR SELECT USING(is_member(business_id));
DROP POLICY IF EXISTS v22_shipment_select ON public.v22_logistics_shipments; CREATE POLICY v22_shipment_select ON public.v22_logistics_shipments FOR SELECT USING(is_member(business_id));
DROP POLICY IF EXISTS v22_milestone_select ON public.v22_logistics_milestones; CREATE POLICY v22_milestone_select ON public.v22_logistics_milestones FOR SELECT USING(is_member(business_id));
DROP POLICY IF EXISTS v22_exception_select ON public.v22_supply_exceptions; CREATE POLICY v22_exception_select ON public.v22_supply_exceptions FOR SELECT USING(is_member(business_id));
DROP POLICY IF EXISTS v22_metrics_select ON public.v22_supplier_logistics_metrics; CREATE POLICY v22_metrics_select ON public.v22_supplier_logistics_metrics FOR SELECT USING(is_member(business_id));
REVOKE INSERT,UPDATE,DELETE ON public.v22_supplier_confirmations FROM authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.v22_supplier_confirmation_lines FROM authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.v22_logistics_shipments FROM authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.v22_logistics_milestones FROM authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.v22_supply_exceptions FROM authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.v22_supplier_logistics_metrics FROM authenticated;
CREATE OR REPLACE FUNCTION public.v22_sync_po_shipment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.status='sent' AND old.status<>'sent' THEN INSERT INTO public.v22_logistics_shipments(business_id,shipment_type,purchase_order_id,supplier_id,status,planned_at,expected_at,supplier_reference) VALUES(new.business_id,'supplier_po',new.id,new.supplier_id,'planned',coalesce(new.ordered_at,now()),new.expected_at,null) ON CONFLICT(purchase_order_id) DO UPDATE SET expected_at=coalesce(excluded.expected_at,public.v22_logistics_shipments.expected_at); INSERT INTO public.v22_logistics_milestones(business_id,shipment_id,milestone_code,occurred_at,source,notes,created_by) SELECT new.business_id,s.id,'planned',coalesce(new.ordered_at,now()),'system','PO sent; logistics tracking opened',auth.uid() FROM public.v22_logistics_shipments s WHERE s.purchase_order_id=new.id AND NOT EXISTS(select 1 from public.v22_logistics_milestones m where m.shipment_id=s.id and m.milestone_code='planned'); END IF; IF new.expected_at IS DISTINCT FROM old.expected_at THEN UPDATE public.v22_logistics_shipments SET expected_at=new.expected_at WHERE purchase_order_id=new.id; END IF; IF new.status='received' AND old.status<>'received' THEN UPDATE public.v22_logistics_shipments SET status='delivered',delivered_at=coalesce(new.received_at,now()) WHERE purchase_order_id=new.id; END IF; IF new.status='cancelled' AND old.status<>'cancelled' THEN UPDATE public.v22_logistics_shipments SET status='cancelled' WHERE purchase_order_id=new.id AND status<>'delivered'; END IF; RETURN new; END $$;
DROP TRIGGER IF EXISTS v22_po_shipment_sync ON public.purchase_orders; CREATE TRIGGER v22_po_shipment_sync AFTER UPDATE ON public.purchase_orders FOR EACH ROW EXECUTE FUNCTION public.v22_sync_po_shipment();
CREATE OR REPLACE FUNCTION public.v22_sync_transfer_shipment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.status='in_transit' AND old.status<>'in_transit' THEN INSERT INTO public.v22_logistics_shipments(business_id,shipment_type,stock_transfer_id,status,origin_location_id,destination_location_id,dispatched_at) VALUES(new.business_id,'internal_transfer',new.id,'in_transit',new.source_location_id,new.destination_location_id,new.dispatched_at) ON CONFLICT(stock_transfer_id) DO UPDATE SET status='in_transit',dispatched_at=coalesce(excluded.dispatched_at,public.v22_logistics_shipments.dispatched_at); END IF; IF new.status='received' AND old.status<>'received' THEN UPDATE public.v22_logistics_shipments SET status='delivered',delivered_at=coalesce(new.received_at,now()) WHERE stock_transfer_id=new.id; END IF; IF new.status='cancelled' AND old.status<>'cancelled' THEN UPDATE public.v22_logistics_shipments SET status='cancelled' WHERE stock_transfer_id=new.id AND status<>'delivered'; END IF; RETURN new; END $$;
DROP TRIGGER IF EXISTS v22_transfer_shipment_sync ON public.stock_transfers; CREATE TRIGGER v22_transfer_shipment_sync AFTER UPDATE ON public.stock_transfers FOR EACH ROW EXECUTE FUNCTION public.v22_sync_transfer_shipment();
CREATE OR REPLACE FUNCTION public.record_v22_supplier_confirmation(p_purchase_order_id uuid,p_expected_at timestamptz,p_supplier_reference text,p_lines jsonb,p_notes text default null) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.purchase_orders; c_id uuid; s public.v22_logistics_shipments; item jsonb; pol public.purchase_order_lines; confirmed numeric(24,8); u text; all_confirmed boolean:=true; BEGIN SELECT * INTO p FROM public.purchase_orders WHERE id=p_purchase_order_id FOR UPDATE; IF p.id IS NULL THEN RAISE EXCEPTION 'Purchase order not found'; END IF; IF NOT has_role(p.business_id,ARRAY['owner','manager']::member_role[]) THEN RAISE EXCEPTION 'Manager authorization required'; END IF; IF p.status NOT IN ('approved','sent','partially_received') THEN RAISE EXCEPTION 'PO is not confirmable in status %',p.status; END IF; IF jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines)=0 THEN RAISE EXCEPTION 'Confirmation lines are required'; END IF; INSERT INTO public.v22_supplier_confirmations(business_id,purchase_order_id,expected_at,supplier_reference,confirmed_by,notes) VALUES(p.business_id,p.id,p_expected_at,p_supplier_reference,auth.uid(),p_notes) RETURNING id INTO c_id; FOR item IN SELECT * FROM jsonb_array_elements(p_lines) LOOP SELECT * INTO pol FROM public.purchase_order_lines WHERE id=(item->>'purchase_order_line_id')::uuid AND purchase_order_id=p.id FOR UPDATE; IF pol.id IS NULL THEN RAISE EXCEPTION 'Purchase order line is outside the PO'; END IF; confirmed:=coalesce((item->>'confirmed_quantity')::numeric,0); u:=item->>'unit'; IF confirmed<0 OR confirmed>pol.ordered_quantity-pol.received_quantity THEN RAISE EXCEPTION 'Invalid confirmed quantity for line %',pol.id; END IF; IF u IS NULL OR u<>pol.unit THEN RAISE EXCEPTION 'Exact-unit mismatch on PO line %',pol.id; END IF; INSERT INTO public.v22_supplier_confirmation_lines(business_id,confirmation_id,purchase_order_line_id,ingredient_id,confirmed_quantity,unit) VALUES(p.business_id,c_id,pol.id,pol.ingredient_id,confirmed,pol.unit); IF confirmed < pol.ordered_quantity-pol.received_quantity THEN all_confirmed:=false; END IF; END LOOP; UPDATE public.purchase_orders SET expected_at=coalesce(p_expected_at,expected_at) WHERE id=p.id AND status IN ('approved','sent','partially_received'); SELECT * INTO s FROM public.v22_logistics_shipments WHERE purchase_order_id=p.id FOR UPDATE; IF s.id IS NULL THEN INSERT INTO public.v22_logistics_shipments(business_id,shipment_type,purchase_order_id,supplier_id,status,supplier_reference,expected_at,confirmed_at) VALUES(p.business_id,'supplier_po',p.id,p.supplier_id,'confirmed',p_supplier_reference,p_expected_at,now()) RETURNING * INTO s; ELSE UPDATE public.v22_logistics_shipments SET status='confirmed',supplier_reference=coalesce(p_supplier_reference,supplier_reference),expected_at=coalesce(p_expected_at,expected_at),confirmed_at=now() WHERE id=s.id; END IF; INSERT INTO public.v22_logistics_milestones(business_id,shipment_id,milestone_code,occurred_at,source,notes,created_by) VALUES(p.business_id,s.id,'supplier_confirmed',now(),'supplier',case when all_confirmed then 'Supplier confirmed all open PO quantities' else 'Supplier issued partial confirmation' end,auth.uid()); IF NOT all_confirmed THEN INSERT INTO public.v22_supply_exceptions(business_id,shipment_id,purchase_order_id,exception_type,severity,details) VALUES(p.business_id,s.id,p.id,'partial_confirmation','high',jsonb_build_object('confirmation_id',c_id)); END IF; RETURN c_id; END $$;
CREATE OR REPLACE FUNCTION public.record_v22_logistics_milestone(p_shipment_id uuid,p_milestone_code text,p_occurred_at timestamptz default now(),p_source text default 'user',p_notes text default null) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.v22_logistics_shipments; m_id uuid; current_rank integer; new_rank integer; BEGIN SELECT * INTO s FROM public.v22_logistics_shipments WHERE id=p_shipment_id FOR UPDATE; IF s.id IS NULL THEN RAISE EXCEPTION 'Shipment not found'; END IF; IF NOT has_role(s.business_id,ARRAY['owner','manager','staff']::member_role[]) THEN RAISE EXCEPTION 'Not authorized for this business'; END IF; IF p_milestone_code NOT IN ('planned','supplier_confirmed','dispatched','in_transit','out_for_delivery','delivered','exception') THEN RAISE EXCEPTION 'Unsupported milestone'; END IF; current_rank:=case s.status when 'planned' then 1 when 'confirmed' then 2 when 'in_transit' then 4 when 'out_for_delivery' then 5 when 'delivered' then 6 when 'exception' then 7 else 1 end; new_rank:=case p_milestone_code when 'planned' then 1 when 'supplier_confirmed' then 2 when 'dispatched' then 3 when 'in_transit' then 4 when 'out_for_delivery' then 5 when 'delivered' then 6 when 'exception' then 7 end; IF new_rank<current_rank AND p_milestone_code<>'exception' THEN RAISE EXCEPTION 'Milestone cannot move shipment backwards'; END IF; INSERT INTO public.v22_logistics_milestones(business_id,shipment_id,milestone_code,occurred_at,source,notes,created_by) VALUES(s.business_id,s.id,p_milestone_code,p_occurred_at,p_source,p_notes,auth.uid()) RETURNING id INTO m_id; UPDATE public.v22_logistics_shipments SET status=case p_milestone_code when 'supplier_confirmed' then 'confirmed' when 'dispatched' then 'in_transit' when 'in_transit' then 'in_transit' when 'out_for_delivery' then 'out_for_delivery' when 'delivered' then 'delivered' when 'exception' then 'exception' else status end,confirmed_at=case when p_milestone_code='supplier_confirmed' then coalesce(confirmed_at,p_occurred_at) else confirmed_at end,dispatched_at=case when p_milestone_code='dispatched' then coalesce(dispatched_at,p_occurred_at) else dispatched_at end,delivered_at=case when p_milestone_code='delivered' then coalesce(delivered_at,p_occurred_at) else delivered_at end WHERE id=s.id; IF p_milestone_code='exception' THEN INSERT INTO public.v22_supply_exceptions(business_id,shipment_id,purchase_order_id,stock_transfer_id,exception_type,severity,details) VALUES(s.business_id,s.id,s.purchase_order_id,s.stock_transfer_id,'route_blocked','high',jsonb_build_object('milestone_id',m_id,'notes',p_notes)); END IF; RETURN m_id; END $$;
CREATE OR REPLACE FUNCTION public.refresh_v22_supply_exceptions(p_business_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer:=0; BEGIN IF NOT has_role(p_business_id,ARRAY['owner','manager']::member_role[]) THEN RAISE EXCEPTION 'Manager authorization required'; END IF; INSERT INTO public.v22_supply_exceptions(business_id,shipment_id,purchase_order_id,stock_transfer_id,exception_type,severity,details) SELECT s.business_id,s.id,s.purchase_order_id,s.stock_transfer_id,'eta_breach',case when s.expected_at < now()-interval '2 days' then 'critical' else 'high' end,jsonb_build_object('expected_at',s.expected_at,'now',now()) FROM public.v22_logistics_shipments s WHERE s.business_id=p_business_id AND s.status IN ('planned','confirmed','in_transit','out_for_delivery') AND s.expected_at IS NOT NULL AND s.expected_at<now() AND NOT EXISTS(select 1 from public.v22_supply_exceptions e where e.business_id=s.business_id and e.shipment_id=s.id and e.exception_type='eta_breach' and e.status in ('open','acknowledged')) ON CONFLICT DO NOTHING; INSERT INTO public.v22_supply_exceptions(business_id,shipment_id,purchase_order_id,exception_type,severity,details) SELECT s.business_id,s.id,s.purchase_order_id,'supplier_confirmation_overdue','medium',jsonb_build_object('sent_at',po.sent_at) FROM public.v22_logistics_shipments s JOIN public.purchase_orders po ON po.id=s.purchase_order_id WHERE s.business_id=p_business_id AND s.shipment_type='supplier_po' AND po.status IN ('sent','partially_received') AND po.sent_at IS NOT NULL AND po.sent_at<now()-interval '24 hours' AND NOT EXISTS(select 1 from public.v22_supplier_confirmations c where c.purchase_order_id=po.id) AND NOT EXISTS(select 1 from public.v22_supply_exceptions e where e.business_id=s.business_id and e.shipment_id=s.id and e.exception_type='supplier_confirmation_overdue' and e.status in ('open','acknowledged')) ON CONFLICT DO NOTHING; SELECT count(*) INTO n FROM public.v22_supply_exceptions WHERE business_id=p_business_id AND status IN ('open','acknowledged'); INSERT INTO public.audit_logs(business_id,user_id,action,entity_type,metadata) VALUES(p_business_id,auth.uid(),'SupplyExceptionsRefreshed','v22_supply_exception',jsonb_build_object('active_exception_count',n)); RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.resolve_v22_supply_exception(p_exception_id uuid,p_status text,p_notes text default null) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.v22_supply_exceptions; BEGIN SELECT * INTO e FROM public.v22_supply_exceptions WHERE id=p_exception_id FOR UPDATE; IF e.id IS NULL THEN RAISE EXCEPTION 'Exception not found'; END IF; IF NOT has_role(e.business_id,ARRAY['owner','manager']::member_role[]) THEN RAISE EXCEPTION 'Manager authorization required'; END IF; IF p_status NOT IN ('acknowledged','resolved') THEN RAISE EXCEPTION 'Invalid exception status'; END IF; IF e.status='resolved' THEN RAISE EXCEPTION 'Exception already resolved'; END IF; UPDATE public.v22_supply_exceptions SET status=p_status,acknowledged_at=case when p_status in ('acknowledged','resolved') then coalesce(acknowledged_at,now()) else acknowledged_at end,resolved_at=case when p_status='resolved' then now() else resolved_at end,resolved_by=case when p_status='resolved' then auth.uid() else resolved_by end,details=details||case when p_notes is null then '{}'::jsonb else jsonb_build_object('resolution_notes',p_notes) end WHERE id=e.id; END $$;
CREATE OR REPLACE FUNCTION public.refresh_v22_supplier_logistics_metrics(p_business_id uuid,p_window_days integer default 365) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF NOT has_role(p_business_id,ARRAY['owner','manager']::member_role[]) THEN RAISE EXCEPTION 'Manager authorization required'; END IF; IF p_window_days<1 OR p_window_days>3650 THEN RAISE EXCEPTION 'Invalid window'; END IF; WITH sh AS (SELECT s.* FROM public.v22_logistics_shipments s WHERE s.business_id=p_business_id AND s.shipment_type='supplier_po' AND s.created_at>=now()-make_interval(days=>p_window_days)), agg AS (SELECT supplier_id,count(*) shipment_count,count(*) filter(where confirmed_at is not null) confirmed_count,count(*) filter(where delivered_at is not null and (expected_at is null or delivered_at<=expected_at)) on_time_eta_count,count(*) filter(where delivered_at is not null) delivered_count FROM sh GROUP BY supplier_id) INSERT INTO public.v22_supplier_logistics_metrics(business_id,supplier_id,shipment_count,confirmed_count,on_time_eta_count,delivered_count,confirmation_rate,eta_accuracy_score,logistics_execution_score,calculated_at) SELECT p_business_id,s.id,coalesce(a.shipment_count,0),coalesce(a.confirmed_count,0),coalesce(a.on_time_eta_count,0),coalesce(a.delivered_count,0),case when coalesce(a.shipment_count,0)=0 then 0 else round(100.0*a.confirmed_count/a.shipment_count,4) end,case when coalesce(a.delivered_count,0)=0 then 0 else round(100.0*a.on_time_eta_count/a.delivered_count,4) end,case when coalesce(a.shipment_count,0)=0 then 0 else round(100.0*((a.confirmed_count::numeric/a.shipment_count)*0.40+case when a.delivered_count=0 then 0 else (a.on_time_eta_count::numeric/a.delivered_count)*0.60 end),4) end,now() FROM public.suppliers s LEFT JOIN agg a ON a.supplier_id=s.id WHERE s.business_id=p_business_id ON CONFLICT(business_id,supplier_id) DO UPDATE SET shipment_count=excluded.shipment_count,confirmed_count=excluded.confirmed_count,on_time_eta_count=excluded.on_time_eta_count,delivered_count=excluded.delivered_count,confirmation_rate=excluded.confirmation_rate,eta_accuracy_score=excluded.eta_accuracy_score,logistics_execution_score=excluded.logistics_execution_score,calculated_at=now(); SELECT count(*) INTO n FROM public.v22_supplier_logistics_metrics WHERE business_id=p_business_id; INSERT INTO public.audit_logs(business_id,user_id,action,entity_type,metadata) VALUES(p_business_id,auth.uid(),'SupplierLogisticsSnapshot','v22_supplier_logistics_metrics',jsonb_build_object('supplier_count',n,'window_days',p_window_days)); RETURN n; END $$;
CREATE OR REPLACE VIEW public.view_v22_logistics_control_tower AS SELECT s.business_id,count(*) filter(where s.status in ('planned','confirmed','in_transit','out_for_delivery','exception')) active_shipments,count(*) filter(where s.status='in_transit') in_transit_shipments,count(*) filter(where s.status='out_for_delivery') out_for_delivery_shipments,count(*) filter(where s.status='delivered' and s.delivered_at>=now()-interval '30 days') delivered_30d,count(*) filter(where s.expected_at is not null and s.expected_at<now() and s.status not in ('delivered','cancelled')) overdue_shipments,count(*) filter(where s.expected_at is not null and s.expected_at<=now()+interval '7 days' and s.status not in ('delivered','cancelled')) due_7d,count(*) filter(where s.expected_at is not null and s.expected_at<=now()+interval '30 days' and s.status not in ('delivered','cancelled')) due_30d,count(*) filter(where s.shipment_type='supplier_po') supplier_shipments,count(*) filter(where s.shipment_type='internal_transfer') transfer_shipments,(select count(*) from public.v22_supply_exceptions e where e.business_id=s.business_id and e.status in ('open','acknowledged')) active_exceptions,(select count(*) from public.v22_supply_exceptions e where e.business_id=s.business_id and e.status in ('open','acknowledged') and e.severity in ('high','critical')) high_exceptions FROM public.v22_logistics_shipments s GROUP BY s.business_id;
CREATE OR REPLACE VIEW public.view_v22_active_exceptions AS SELECT e.*,s.status as shipment_status,s.expected_at,s.supplier_id FROM public.v22_supply_exceptions e LEFT JOIN public.v22_logistics_shipments s ON s.id=e.shipment_id WHERE e.status in ('open','acknowledged');
GRANT EXECUTE ON FUNCTION public.record_v22_supplier_confirmation(uuid,timestamptz,text,jsonb,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.record_v22_logistics_milestone(uuid,text,timestamptz,text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_v22_supply_exceptions(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.resolve_v22_supply_exception(uuid,text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_v22_supplier_logistics_metrics(uuid,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.v22_audit_milestone() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(business_id,user_id,action,entity_type,entity_id,metadata) VALUES(new.business_id,coalesce(new.created_by,auth.uid()),'LogisticsMilestoneRecorded','v22_logistics_milestone',new.id,jsonb_build_object('shipment_id',new.shipment_id,'milestone',new.milestone_code,'occurred_at',new.occurred_at,'source',new.source)); RETURN new; END $$;
DROP TRIGGER IF EXISTS v22_milestone_audit ON public.v22_logistics_milestones; CREATE TRIGGER v22_milestone_audit AFTER INSERT ON public.v22_logistics_milestones FOR EACH ROW EXECUTE FUNCTION public.v22_audit_milestone();